                            @field(output, (if (@typeInfo(@TypeOf(field)) == .@"enum" or @typeInfo(@TypeOf(field)) == .@"union") @tagName(field) else field.name)) = css.generic.deepClone(field.@"type", (&@field(input, (if (@typeInfo(@TypeOf(field)) == .@"enum" or @typeInfo(@TypeOf(field)) == .@"union") @tagName(field) else field.name))), context.allocator);
                        }
                    }
                    _ = bun.handleOom(dest.append(context.allocator, .{ .@"box-shadow" = .{ p3, VendorPrefix.NONE } }));
                }
                if (fallbacks.lab) {
                    var lab = SmallList(BoxShadow, 1).initCapacity(context.allocator, box_shadows_list.len());
                    _ = &lab;
                    _ = lab.setLen(box_shadows_list.len());
                    const src_slice = box_shadows_list.slice();
                    const dst_slice = lab.slice_mut();
                    var i: usize = 0;
                    _ = &i;
                    while ((i < src_slice.len)) : (i = (i + 1)) {
                        const input = (&src_slice[@as(usize, @intCast(i))]);
                        var output = (&dst_slice[@as(usize, @intCast(i))]);
                        _ = &output;
                        const lab_color = input.color.toLAB(context.allocator);
                        if (lab_color) |lc| {
                            _ = &lc;
                            output.color = lc;
                        } else {
                            output.color = input.color.deepClone(context.allocator);
                        }
                        const fields = std.@"meta".fields(BoxShadow);
                        inline for (fields) |field| {
                            if (comptime std.mem.eql(u8, (if (@typeInfo(@TypeOf(field)) == .@"enum" or @typeInfo(@TypeOf(field)) == .@"union") @tagName(field) else field.name), "color")) {
                                continue;
                            }
                            @field(output, (if (@typeInfo(@TypeOf(field)) == .@"enum" or @typeInfo(@TypeOf(field)) == .@"union") @tagName(field) else field.name)) = css.generic.deepClone(field.@"type", (&@field(input, (if (@typeInfo(@TypeOf(field)) == .@"enum" or @typeInfo(@TypeOf(field)) == .@"union") @tagName(field) else field.name))), context.allocator);
                        }
                    }
                    _ = bun.handleOom(dest.append(context.allocator, .{ .@"box-shadow" = .{ lab, VendorPrefix.NONE } }));
                } else {
                    _ = bun.handleOom(dest.append(context.allocator, .{ .@"box-shadow" = .{ box_shadows_list, prefixes } }));
                }
            } else {
                _ = bun.handleOom(dest.append(context.allocator, .{ .@"box-shadow" = .{ box_shadows_list, prefixes2 } }));
            }
            self.flushed = true;
    }
};

const SmallList = css.SmallList;
const Printer = css.Printer;
const PrintErr = css.PrintErr;
const CssColor = css.css_values.color.CssColor;
const Length = css.css_values.length.Length;
const VendorPrefix = css.VendorPrefix;
const Property = css.Property;
const Feature = css.prefixes.Feature;
const BoxShadowsAndPrefix = struct { SmallList(BoxShadow, 1), VendorPrefix };
const Allocator = std.mem.Allocator;
